from pathlib import Path
import hashlib,json,subprocess as sp,re
p=Path(__file__).parent;out={}
def method(source,signature):
 start=source.index(signature);begin=source.index('{',start);depth=1;i=begin+1
 while depth:
  if source[i]=='{':depth+=1
  elif source[i]=='}':depth-=1
  i+=1
 return source[start:i]
for lib,signatures in{'ruf':['static std::size_t checked_size(std::size_t n)','void check(int i) const','int leader_unchecked(int i) const','void undo_last() noexcept','bool unite(int x, int y)','bool same(int a, int b) const','void undo()','void rollback(int state = -1)','void clear_history() noexcept','void reserve_history(std::size_t count)'], 'rwuf':['int find_unchecked(int v) const','static bool try_add(T a, T b, T& out)','static bool try_subtract(T a, T b, T& out)','NarrowRootWeight narrow_root_weight(int v) const','MergeResult record_merge(int parent, int child, T gap)','MergeResult unite_wide(int x, int y, const T& w)','MergeResult unite_impl(int x, int y, const T& w)','void undo_unchecked() noexcept','std::pair<int, T> root_with_weight_slow(int v) const','T diff_slow(int x, int y) const','RollbackWeightedUnionFind& operator=(RollbackWeightedUnionFind other) noexcept','void clear()','std::optional<T> try_diff(int x, int y) const','T diff(int x, int y) const','bool consistent(int x, int y, const T& w) const','void clear_history() noexcept','void reserve_history(std::size_t calls)','void undo()','void rollback(int state = -1)','std::vector<std::vector<int>> groups() const']}.items():
 base=(p/lib/'baseline.hpp').read_text();final=(p/lib/'final.hpp').read_text();rows={}
 for signature in signatures:
  a,b=method(base,signature),method(final,signature);assert a==b,(lib,signature);rows[signature]={'byte_identical':True,'sha256':hashlib.sha256(a.encode()).hexdigest()}
 out[lib]={'methods':rows}
 if lib=='rwuf':
  a=base[base.index('    static constexpr bool checked_integer'):base.index('    void reset(int n)')];b=final[final.index('    static constexpr bool checked_integer'):final.index('    void reset(int n)')];assert a==b;out[lib]['all_math_storage_constructor_copy_move_before_reset']={'byte_identical':True,'sha256':hashlib.sha256(a.encode()).hexdigest()}
# GCC RUFの.text全体差は、未変更のvector破棄関数の配置順とパディングのみかを調べる。
def disasm(path):
 s=sp.check_output(['objdump','-d','-C','--no-show-raw-insn',str(path)],text=True);blocks={};current=None
 for line in s.splitlines():
  m=re.match(r'^[0-9a-f]+ <(.*)>:$',line)
  if m:current=m[1];blocks[current]=[];continue
  if current is None or not re.match(r'^\s*[0-9a-f]+:',line):continue
  line=re.sub(r'^\s*[0-9a-f]+:\s*','',line);line=re.sub(r'\b[0-9a-f]+\s*(?=<)','',line)
  if 'nop' in line:continue
  blocks[current].append(line)
 return blocks
for lib in['ruf','rwuf']:
 for cc in['gcc','clang']:
  a,b=disasm(p/lib/f'final_main_{cc}_baseline_1'),disasm(p/lib/f'final_main_{cc}_final_1');assert set(a)==set(b);differ=[name for name in a if a[name]!=b[name]];assert not differ,(lib,cc,differ);out[lib][cc+'_main_symbolic_instructions']={'all_functions_identical_ignoring_addresses_and_nops':True,'functions':len(a)}
(p/'method_identity.json').write_text(json.dumps(out,indent=2)+'\n');print('unchanged hot methods and symbolic main instructions passed')
